/**
 * Broken files must fail on their own, quickly, with a message a person can
 * read, and must never take the good files in the same batch down with them.
 * The fixtures are generated by test/make-fixtures.mjs.
 */
import { readFileSync } from 'fs';
import { parseBuffer } from 'music-metadata';
import { readFileTags, saveFile, acceptsFile, ReadError, type FileTags } from '../src/lib/tags';
import { buildFilename, sanitizeSegment } from '../src/lib/filename';

let failures = 0;
const ok = (cond: boolean, msg: string) => {
  console.log(`${cond ? '  PASS' : '  FAIL'}  ${msg}`);
  if (!cond) failures++;
};

/** A read this slow on a tiny file means a parser is looping, not working. */
const SLOW_MS = 2000;

function load(name: string): ArrayBuffer {
  const b = readFileSync(`test/fixtures/${name}`);
  return b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) as ArrayBuffer;
}

async function timedRead(name: string): Promise<{ tags?: FileTags; error?: unknown; ms: number }> {
  const t = performance.now();
  try {
    const tags = await readFileTags(load(name));
    return { tags, ms: performance.now() - t };
  } catch (error) {
    return { error, ms: performance.now() - t };
  }
}

/** Write the file back in its own format, the path that never decodes audio. */
async function saveSame(name: string, tags: FileTags, title = tags.editable.title) {
  return saveFile({
    buffer: load(name),
    format: tags.format,
    editable: { ...tags.editable, title },
    cover: tags.cover,
    carried: tags.carried,
    outputFormat: tags.format,
  });
}

async function parsed(blob: Blob, format: 'mp3' | 'm4a') {
  return parseBuffer(new Uint8Array(await blob.arrayBuffer()), { mimeType: format === 'mp3' ? 'audio/mpeg' : 'audio/mp4' });
}

/** A parser error passed through verbatim would be English and technical. */
const readable = (e: unknown) => e instanceof ReadError && /^[A-ZÆØÅ].*\.$/.test(e.message) && !/ID3v2|exceeds|offset/i.test(e.message);

console.log('\n--- afkortet MP3 ---');
{
  const tag = await timedRead('bad-truncated-tag.mp3');
  ok(tag.ms < SLOW_MS, `afkortet inde i tagget: svar efter ${tag.ms.toFixed(0)} ms`);
  ok(!!tag.error, 'afkortet inde i tagget afvises');
  ok(readable(tag.error), `fejlbeskeden er til at forstå: "${(tag.error as Error)?.message}"`);

  const audio = await timedRead('bad-truncated-audio.mp3');
  ok(audio.ms < SLOW_MS, `afkortet i lyden: svar efter ${audio.ms.toFixed(0)} ms`);
  ok(audio.tags?.editable.title === 'Blæsten går frisk', 'afkortet i lyden: tagget kan stadig læses');
  if (audio.tags) {
    const out = await saveSame('bad-truncated-audio.mp3', audio.tags, 'Ny titel');
    ok((await parsed(out.blob, 'mp3')).common.title === 'Ny titel', 'afkortet i lyden: kan stadig gemmes med ny titel');
  }
}

console.log('\n--- MP4 med stsd-størrelse 0 ---');
{
  const r = await timedRead('bad-stsd-zero.m4a');
  ok(r.ms < SLOW_MS, `ingen uendelig løkke: svar efter ${r.ms.toFixed(0)} ms`);
  ok(r.tags?.format === 'm4a' && r.tags.editable.title === 'Blæsten går frisk', 'tags læses trods defekt stsd');
  if (r.tags) {
    const t = performance.now();
    const out = await saveSame('bad-stsd-zero.m4a', r.tags, 'Ny titel');
    // music-metadata rejects the still-broken stsd, so read it back the way the app does.
    const again = await readFileTags(await out.blob.arrayBuffer());
    ok(performance.now() - t < SLOW_MS, 'gemning og genlæsning hænger ikke');
    ok(again.editable.title === 'Ny titel', 'kan gemmes som M4A med ny titel');
  }
}

console.log('\n--- covers ---');
{
  const defect = await timedRead('bad-cover-defect.mp3');
  ok(defect.ms < SLOW_MS && !!defect.tags, 'fil med defekt cover kan læses');
  if (defect.tags) {
    const out = await saveSame('bad-cover-defect.mp3', defect.tags);
    ok(out.failed.includes('Coverbillede'), 'et cover der ikke er et billede meldes som ikke skrevet, i stedet for at forsvinde stille');
    ok((await parsed(out.blob, 'mp3')).common.title === 'Cover-test', 'resten af filen gemmes alligevel');
  }

  const huge = await timedRead('bad-cover-huge.mp3');
  ok(huge.ms < SLOW_MS, `12 MB cover: svar efter ${huge.ms.toFixed(0)} ms`);
  ok((huge.tags?.cover?.data.byteLength ?? 0) >= 12 * 1024 * 1024, 'det store cover læses helt');
  if (huge.tags) {
    const out = await saveSame('bad-cover-huge.mp3', huge.tags, 'Stor');
    ok((await parsed(out.blob, 'mp3')).common.title === 'Stor', 'fil med stort cover kan gemmes');
  }
}

console.log('\n--- forkert filendelse ---');
{
  const m4a = await timedRead('bad-m4a-named.mp3');
  ok(m4a.tags?.format === 'm4a', 'M4A med endelsen .mp3 genkendes som M4A');
  const mp3 = await timedRead('bad-mp3-named.m4a');
  ok(mp3.tags?.format === 'mp3', 'MP3 med endelsen .m4a genkendes som MP3');

  ok(acceptsFile('bad-png-named.mp3'), 'en PNG med endelsen .mp3 slipper forbi filtret på navn');
  const png = await timedRead('bad-png-named.mp3');
  ok(png.error instanceof ReadError && /Ukendt filformat/.test((png.error as Error).message), 'men afvises ved læsning som ukendt format');
}

console.log('\n--- HTML og kontroltegn ---');
{
  const r = await timedRead('bad-html-tags.mp3');
  ok(!!r.tags, 'fil med HTML i tags kan læses');
  const e = r.tags!.editable;
  ok(e.title.includes('<img src=x onerror=alert(1)>'), 'HTML i titlen bevares som tekst, ikke fjernet eller tolket');
  ok(e.album === '</textarea><script>alert(1)</script>', 'HTML i albummet bevares som tekst');

  const name = buildFilename({
    pattern: 'title-artist',
    tags: e,
    originalName: '<script>alert(1)</script>\u0001.mp3',
    extension: '.mp3',
  });
  // Control characters are exactly what this test looks for.
  // oxlint-disable-next-line no-control-regex
  ok(!/[\u0000-\u001f\u007f<>:"/\\|?*]/.test(name), `filnavnet fra tags er sikkert: ${JSON.stringify(name)}`);
  const original = buildFilename({ pattern: 'original', tags: e, originalName: '<b>Spor</b>\u0007\u001b.mp3', extension: '.mp3' });
  // oxlint-disable-next-line no-control-regex
  ok(!/[\u0000-\u001f\u007f<>]/.test(original), `"Som originalen" renser også: ${JSON.stringify(original)}`);
  ok(sanitizeSegment('a\u0000b\u0007c\u001bd\u007fe') === 'abcde', 'kontroltegn fjernes fra filnavne');
}

console.log('\n--- batch med én defekt fil ---');
{
  // The same loop shape as the app: every file read and written on its own.
  const batch = ['tagged.mp3', 'bad-truncated-tag.mp3', 'faststart.m4a', 'bad-png-named.mp3'];
  const written: string[] = [];
  const failed: string[] = [];
  for (const name of batch) {
    try {
      const tags = await readFileTags(load(name));
      const out = await saveSame(name, tags, `Batch ${name}`);
      const md = await parsed(out.blob, tags.format);
      if (md.common.title === `Batch ${name}` && md.common.artist === 'Søren Ødegård') written.push(name);
    } catch {
      failed.push(name);
    }
  }
  ok(written.join() === 'tagged.mp3,faststart.m4a', `de gode filer skrives korrekt: ${written.join(', ')}`);
  ok(failed.join() === 'bad-truncated-tag.mp3,bad-png-named.mp3', `kun de defekte fejler: ${failed.join(', ')}`);
}

console.log(`\n${failures === 0 ? 'ALL PASS' : failures + ' FAILURE(S)'}\n`);
process.exit(failures === 0 ? 0 : 1);
